window.updateFarmPage=function(){
  const s=currentFarm();
  main.innerHTML=header('Update my farm','Keep today’s date, animals, skills, tools, goal, and farm picture in one place. Saving refreshes your Home plan everywhere you sign in.')+`<section class="farm-editor" id="update-farm"><form id="farmForm"><div class="editor-group"><h3>Today</h3><div class="editable-grid">${inputField('Season','season','select',['Spring','Summer','Fall','Winter'])}${inputField('Day','day')}${inputField('Year','year')}${inputField('Weather','weather','select',['Sunny','Rainy','Snowy','Stormy'])}${inputField('Daily luck','luck','select',['Very good','Good','Neutral','Bad'])}${inputField('Gold','gold')}</div></div><div class="editor-group"><h3>Animals & supplies</h3><div class="editable-grid compact-fields">${inputField('Hay','hay')}${inputField('Chickens','chickens')}${inputField('Cows','cows')}${inputField('Ducks','ducks')}${inputField('Goats','goats')}${inputField('Sheep','sheep')}${inputField('Rabbits','rabbits')}${inputField('Pigs','pigs')}${inputField('Mayo machines','mayoMachines')}${inputField('Cheese presses','cheesePresses')}</div></div><details class="more-farm-fields"><summary>Skills, tools & machines</summary><div class="editor-group"><div class="editable-grid compact-fields">${inputField('Farming','farming')}${inputField('Mining','mining')}${inputField('Foraging','foraging')}${inputField('Fishing','fishing')}${inputField('Combat','combat')}${inputField('Mine floor','mine')}${inputField('Pickaxe','pickaxe','select',['Basic','Copper','Steel','Gold','Iridium'])}${inputField('Axe','axe','select',['Basic','Copper','Steel','Gold','Iridium'])}${inputField('Watering can','watering','select',['Basic','Copper','Steel','Gold','Iridium'])}${inputField('Quality sprinklers','sprinklers')}</div></div></details><div class="field project-field"><label for="farm-project">Current goal or next project</label><input id="farm-project" data-farm="project" type="text" value="${s.project||''}"></div><div class="farm-photo-editor" id="farmPhotoForm"><div class="farm-photo-copy"><h3>Current farm picture</h3><p>Add or replace your latest farm screenshot. It stays synced with your account and appears beside today’s summary on Home.</p><div class="farm-photo-actions"><label class="photo-picker" for="farmPhotoInput">Choose a picture</label><input id="farmPhotoInput" name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><button class="button" id="uploadFarmPhoto" type="button">Upload picture</button><button class="button secondary" id="removeFarmPhoto" type="button">Remove</button></div><p class="tiny" id="photoStatus">JPG, PNG, WebP, or GIF · up to 8 MB</p></div></div><div class="button-row"><button class="button" type="submit">Save farm updates</button><button class="button secondary" id="resetCurrent" type="button">Reset current fields</button><a class="button secondary" href="#dashboard">Back to Home</a></div></form></section>`;
  bindFarmPhoto();
  document.querySelector('#farmForm').onsubmit=e=>{e.preventDefault();const data={};document.querySelectorAll('[data-farm]').forEach(el=>data[el.dataset.farm]=el.type==='number'?Number(el.value):el.value);localStorage.setItem('spellStats',JSON.stringify(data));queueCloudSave();toast('Farm updated · syncing to your account');setTimeout(()=>{location.hash='#dashboard'},250)};
  document.querySelector('#resetCurrent').onclick=()=>{if(confirm('Reset only the editable current farm fields? The frozen baseline will stay.')){localStorage.removeItem('spellStats');queueCloudSave();window.updateFarmPage();toast('Current fields reset')}};
};

