const cropNotes={Parsnip:['Spring','4 days','Single harvest','Fast and inexpensive; useful when you need a quick crop.'],Potato:['Spring','6 days','Single; may yield extra','A steady early-game crop.'],Kale:['Spring','6 days','Scythe harvest','Harvest with the scythe to save a little time.'],'Green Bean':['Spring','10 days','Regrows every 3 days','Trellis crop: leave walking lanes.'],Cauliflower:['Spring','12 days','Single harvest','A 3×3 block can become a giant crop.'],Strawberry:['Spring','8 days','Regrows every 4 days','Seeds are sold at the Egg Festival.'],'Hot Pepper':['Summer','5 days','Regrows every 3 days','Fast repeat harvests.'],Blueberry:['Summer','13 days','Regrows every 4 days','Produces multiple berries per harvest.'],Melon:['Summer','12 days','Single harvest','A 3×3 block can become a giant crop.'],Tomato:['Summer','11 days','Regrows every 4 days','Reliable repeat producer.'],Hops:['Summer','11 days','Regrows daily','Trellis crop; plan access lanes.'],Wheat:['Summer / Fall','4 days','Single; scythe harvest','Can survive the Summer-to-Fall transition.'],'Bok Choy':['Fall','4 days','Single harvest','A quick Fall crop.'],Eggplant:['Fall','5 days','Regrows every 5 days','An early repeat harvest.'],Cranberries:['Fall','7 days','Regrows every 5 days','Produces two berries at each harvest.'],Pumpkin:['Fall','13 days','Single harvest','A 3×3 block can become a giant crop.'],Yam:['Fall','10 days','Single harvest','Useful for cooking and requests.'],Grape:['Fall','10 days','Regrows every 3 days','Trellis crop: keep paths open.'],Powdermelon:['Winter','7 days','Single harvest','Winter crop from special seeds; can become giant.'],'Winter Seeds':['Winter','7 days','Forage crops','Grow Crocus, Crystal Fruit, Snow Yam, or Winter Root.'],'Fiber Seeds':['Any','7 days','Scythe harvest','Need no watering and grow in any season.']};
