window.animalsPage=function(){const s=currentFarm();main.innerHTML=header('Farm animals & artisan goods','What each animal needs, where it lives, and what you can make from its produce.')+`<div class="notice current-note"><strong>Your current notes:</strong> ${s.chickens} chickens · ${s.cows} cow${+s.cows===1?'':'s'} · ${s.ducks} ducks · ${s.goats} goats · ${s.sheep} sheep · ${s.rabbits} rabbits · ${s.pigs} pigs · ${s.hay} hay. <a href="#dashboard">Update on My Farm</a></div><div class="reference-grid animal-grid">${animalData.map(a=>`<article class="reference-card animal-card"><img src="assets/animals/${a[1]}" alt="${a[0]}" loading="lazy"><div><p class="eyebrow">${a[2]} · ${a[3]}</p><h2>${a[0]}</h2><p><strong>Produces:</strong> ${a[4]}</p><p><strong>Make:</strong> ${a[5]}</p></div></article>`).join('')}</div><section class="section"><div class="section-title"><h2>Daily care in plain language</h2></div><div class="card-grid"><article class="card"><h3>Feed</h3><p>Each animal uses one portion a day. They prefer fresh grass outside; use hay indoors, during rain, and through Winter.</p></article><article class="card"><h3>Pet & collect</h3><p>Petting and consistent food build friendship. Collect products, then load the matching machine.</p></article><article class="card"><h3>Doors & weather</h3><p>Open doors for clear non-Winter days. Pigs only find truffles outside and do not find them in Winter or rain.</p></article></div></section><p class="tiny source-note">Animal prices, housing, and produce mechanics: Stardew Valley Wiki.</p>`};

