window.recipesPage=function(){main.innerHTML=header('Energy recipe box','Easy snacks first, then fuller meals. Every card shows ingredients, exact energy and health, buffs, and how you learn it.')+`<section class="easy-food-intro"><img src="assets/recipes/field-snack.png" alt="Field Snack"><div><p class="eyebrow">Easiest right now</p><h2>Start with a Field Snack</h2><p>Craft 1 Acorn + 1 Maple Seed + 1 Pine Cone directly from the crafting menu. No kitchen required.</p><strong>+45 energy · +20 health</strong></div></section><div class="recipe-tools"><input id="recipeSearch" type="search" placeholder="Search food, ingredient, buff, or unlock…" aria-label="Search recipes"><select id="recipeEase" aria-label="Filter recipes"><option value="all">All recipes</option><option value="easy">Easy energy first</option><option value="buff">Foods with buffs</option></select></div><div id="recipeGrid" class="reference-grid recipe-grid"></div><div class="notice"><strong>Cooking access:</strong> most dishes need the kitchen from the first farmhouse upgrade, or a Cookout Kit after Foraging 3. Field Snacks are crafted and need neither. One food buff and one drink buff can be active together.</div><p class="tiny source-note">Energy, health, ingredients, unlocks, buffs, and sprites reference the Stardew Valley Wiki for version 1.6.</p>`;const draw=()=>{const q=document.querySelector('#recipeSearch').value.toLowerCase(),filter=document.querySelector('#recipeEase').value;const rows=recipeData.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).filter(r=>filter==='all'||filter==='buff'&&r.buff!=='No buff'||filter==='easy'&&/easy|no kitchen|two ingredients|excellent/i.test(r.easy));document.querySelector('#recipeGrid').innerHTML=rows.map(r=>`<article class="reference-card recipe-card"><img src="assets/recipes/${r.img}" alt="${r.n}" loading="lazy"><div><div class="recipe-card-head"><div><p class="eyebrow">${r.easy}</p><h2>${r.n}</h2></div><span class="energy-pill">⚡ ${r.energy}</span></div><p><strong>Ingredients:</strong> ${r.ingredients}</p><div class="food-stats"><span>⚡ <b>${r.energy}</b> energy</span><span>♥ <b>${r.health}</b> health</span></div><p><strong>Buff:</strong> ${r.buff}</p><p><strong>Learn it:</strong> ${r.source}</p><p class="recipe-note">${r.note}</p></div></article>`).join('')||'<p>No matching recipes yet.</p>'};draw();document.querySelector('#recipeSearch').oninput=draw;document.querySelector('#recipeEase').onchange=draw};

